def build_report(folder: Path, out: Optional[Path] = None) -> Path:
    folder = Path(folder)
    payload = build_payload(folder)
    r, info = payload["results"], payload["info"]
    set_infos = info.get("sets", {})
    meta_lines = [f"реальных шипиков {info.get('n_real_spines', '—')}, нейронов {info.get('n_real_neurons', '—')}" + (f", сплит {info['split']}" if info.get("split") else ", все нейроны"),
                  "наборы: " + "; ".join(f"{k} n={v.get('n')}" for k, v in set_infos.items()),
                  f"создано {info.get('created', '—')}; перестановок {r['settings']['n_permutations']}, опорных повторений {r['settings']['n_reference']}"]
    ck = {v.get("checkpoint") for v in set_infos.values() if v.get("checkpoint")}
    gd = sorted({str(v.get("guidance")) for v in set_infos.values() if v.get("guidance") is not None})
    sd = sorted({str(v.get("seed")) for v in set_infos.values() if v.get("seed") is not None})
    if ck or gd or sd:
        meta_lines.append(f"контрольная точка {', '.join(sorted(map(str, ck))) or '—'}; guidance {', '.join(gd) or '—'}; seed {', '.join(sd) or '—'}")
    body = [header("Условная генерация шипиков: статистическая проверка",
                   "Воспроизводит ли условный генератор различия между типами клеток и совпадает ли он с реальными шипиками того же типа", meta_lines)]

    tl = []
    for lab, e in r.get("effects", {}).items():
        tl.append({"label": "A: метрик согласовано" + (f" ({lab})" if lab != "default" else ""), "value": f"{e['n_concordant']} из {e['n_metrics']}", "note": f"воспроизведено {e['n_reproduced']} из {e['n_real_significant']} реальных эффектов; мало образцов: {e['n_underpowered']}", "accent": "pink"})
    for s in payload["sets"][:4]:
        res = r["same_type"][s["key"]]
        t = res["by_pool"][res["own"]]["table"]
        eq = sum(1 for x in t if x["verdict"] == "equivalent")
        tl.append({"label": f"B: {s['title']}", "value": f"{eq} из {len(t)}", "note": "метрик эквивалентны реальным того же типа", "accent": "green"})
    c = r.get("classifier", {}).get("logistic/all")
    if c:
        tl.append({"label": "C: AUC классификатора условия на реальных", "value": f"{c['auc']:.2f}", "note": f"интервал {c['auc_ci'][0]:.2f}–{c['auc_ci'][1]:.2f}"})
    body.append(tiles(tl))
    body.append(note(_summary(payload), title="Итог"))

    pair = r.get("pair") or ["a", "b"]
    a_ru, b_ru = VALUE_RU.get(pair[0], pair[0]), VALUE_RU.get(pair[1], pair[1])
    body.append(section("A. Воспроизводится ли различие между типами", f"Для каждой метрики показан эффект «{a_ru} относительно {b_ru}»: реальный (нейрон — единица, серый) и сгенерированный (розовый), с 95 % интервалами; заполненный маркер — различие значимо (q < 0,05).",
        '<div class="row" style="margin-bottom:10px"><div style="min-width:240px"><select id="sel-a"></select></div></div>'
        + card("Изменение медианы, %", '<div id="plot-forest" class="plot l"></div>', hint="наведите: интервалы, q, статус")
        + card("Таблица согласованности", '<div id="table-a" style="overflow-x:auto"></div>')
        + note([f"**Нулевая гипотеза.** Реальная: распределения медиан нейронов двух типов одинаковы; статистика — разность медиан нейронных медиан; опора — перестановки меток между нейронами; единица — нейрон. Сгенерированная: наборы взяты из одного распределения; статистика — разность медиан; опора — перестановки между образцами; единица — образец. Эффект — отношение медиан с 95 % интервалом бутстрэпа (нейронов у реальных, образцов у сгенерированных).",
                f"**Как читать.** Статус «воспроизведён» требует одинакового знака, значимости и пересечения интервалов. «Мало образцов» ставится, если сгенерированных образцов недостаточно, чтобы увидеть реальный эффект (его модуль меньше минимально обнаружимого при мощности 80 %): такая метрика не считается ни воспроизведённой, ни проваленной. Столбец Δ — разность логарифмов отношений (сгенерированный минус реальный) с интервалом: ноль внутри означает совместимость амплитуд."], title="Что проверяется и как читать", collapsible=True), anchor="sec-a"))

    body.append(section("B. Совпадает ли набор с реальными шипиками того же типа", "Расстояние сгенерированного набора до реальных шипиков своего типа сравнивается с шумовым полом: расстоянием между двумя независимыми реальными выборками из разных нейронов.",
        '<div class="row" style="margin-bottom:10px"><div style="min-width:280px"><select id="sel-b-set"></select></div><div style="min-width:260px"><select id="sel-b-metric"></select></div></div>'
        + '<div class="grid-2e">' + card("Отношение расстояния к 95-му процентилю шума", '<div id="plot-b-bars" class="plot m"></div>', hint="больше 1 — дальше, чем почти любые две реальные выборки")
        + card("Шумовой пол выбранной метрики (W₁/σ)", '<div id="plot-b-ref" class="plot m"></div>', hint="розовая линия — наблюдаемое") + "</div>"
        + '<div class="grid-2e">' + card("Энергетическое расстояние, 11 метрик", '<div id="plot-b-ed" class="plot s"></div>') + card("Корреляционная структура: расстояние между матрицами Спирмена", '<div id="plot-b-corr" class="plot s"></div>') + "</div>"
        + card("Все метрики выбранного набора", '<div id="table-b" style="overflow-x:auto"></div>')
        + card("Контроль чувствительности: наборы против реальных каждого типа", '<div id="plot-b-cross" class="plot m"></div>', hint="расстояние / 95-й процентиль шума; число — p")
        + note(["**Нулевая гипотеза.** Сгенерированные образцы взаимозаменяемы с реальными шипиками того же типа. Статистика — W₁/σ по каждой метрике и энергетическое расстояние стандартизованного вектора. Опора — те же статистики между реальными выборками из двух непересекающихся случайных половин нейронов того же типа (выбор шипиков сбалансирован по нейронам); единица — нейрон. p — доля опорных значений не меньше наблюдаемого, q — Бенджамини–Хохберг по метрикам.",
                "**Эквивалентность.** «Эквивалентно» ставится, если медиана доказуемо отличается меньше чем на заданную долю σ (TOST) и распределение не отвергается; «не отличается, эквивалентность не доказана» — это всего лишь незначимость, она не означает сходства. Контроль чувствительности внизу показывает, что та же процедура отвергает набор для реальных шипиков другого типа: без этого незначимость могла бы быть просто недостатком мощности."], title="Что проверяется и как читать", collapsible=True), anchor="sec-b"))

    body.append(section("C. Классификатор условия", "Классификатор тормозных и возбуждающих, обученный на реальных шипиках, применяется к сгенерированным наборам.",
        '<div class="row" style="margin-bottom:10px"><div style="min-width:300px"><select id="sel-c"></select></div></div>'
        + '<div class="grid-2e">' + card("Доля шипиков, названных тормозными", '<div id="plot-c-frac" class="plot m"></div>', hint="столбец — набор, ромб — ожидание по реальным")
        + card("AUC: реальные и сгенерированные", '<div id="plot-c-auc" class="plot m"></div>') + "</div>"
        + card("Таблица", '<div id="table-c" style="overflow-x:auto"></div>')
        + note(["**Что проверяется.** Если условие работает, шипики набора «тормозные» классификатор должен называть тормозными так же часто, как реальные тормозные (TPR), а набора «возбуждающие» — так же редко, как реальные возбуждающие (FPR); AUC между двумя сгенерированными наборами должен быть близок к реальному. Для набора без условия оценивается эффективная доля тормозных (формула Рогана–Гладена) — она показывает, какую долю тормозных шипиков фактически порождает модель без условия, и сравнивается с долей в обучающих данных.",
                "Классификатор по метрикам, не зависящим от основания, защищён от смещения поиска основания у сгенерированных мешей."], title="Что проверяется и как читать", collapsible=True), anchor="sec-c"))

    body.append(section("D. Отличимость от реальных и структура зависимостей", "Можно ли отличить сгенерированный набор от реальных шипиков классификатором, и насколько он воспроизводит корреляции между метриками.",
        '<div class="row" style="margin-bottom:10px"><div style="min-width:300px"><select id="sel-d"></select></div></div>'
        + '<div class="grid-2e">' + card("AUC классификатора «реальный / сгенерированный»", '<div id="plot-d-auc" class="plot m"></div>', hint="серая полоса — шум двух реальных половин")
        + card("Опорное распределение выбранного набора", '<div id="plot-d-ref" class="plot m"></div>') + "</div>"
        + '<div class="grid-3" style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px">' + card("Спирмен: реальные", '<div id="plot-d-real" class="plot m"></div>') + card("Спирмен: сгенерированные", '<div id="plot-d-gen" class="plot m"></div>')
        + card("Разность (сгенерированные − реальные)", '<div id="plot-d-diff" class="plot m"></div>') + "</div>"
        + note(["**Что проверяется.** AUC около шума двух реальных половин — набор неотличим по 11 метрикам даже обучаемым классификатором; AUC выше шума означает систематическое различие. Матрицы Спирмена показывают, сохраняются ли связи между метриками (например, объём и площадь); числовое расстояние между матрицами сравнивается с шумом реальных половин в разделе B."], title="Как читать", collapsible=True), anchor="sec-d"))

    body.append(section("E. Доза: зависимость эффекта от веса guidance", "Как меняется сгенерированное различие типов с весом guidance и какой вес ближе всего к реальному различию.",
        ('<div class="row" style="margin-bottom:10px"><div style="min-width:260px"><select id="sel-e"></select></div></div><div class="grid-2e">' + card("Изменение медианы, %", '<div id="plot-e-metric" class="plot m"></div>', hint="серая полоса — реальный интервал")
         + card("Амплитуда эффекта β", '<div id="plot-e-beta" class="plot m"></div>', hint="1 — реальная амплитуда") + "</div>"
         + card("Многомерный эффект: энергетическое расстояние между типами", '<div id="plot-e-ed" class="plot s"></div>', hint="ромб — ближайший к реальному")
         + note(["Для каждого веса показан сгенерированный эффект с интервалами; β — наклон регрессии через ноль сгенерированных логарифмов отношений на реальные по метрикам с реальным эффектом (1 — совпадение амплитуды, меньше 1 — эффект слабее, больше 1 — сильнее). Если задан один вес, график сводится к одной точке."], title="Как читать", collapsible=True))
        if r.get("dose") else '<p class="muted">Не заданы наборы с числовым весом guidance для обоих типов.</p>', anchor="sec-e"))

    body.append(section("F. Валидность", "Доли образцов, прошедших каждый шаг, с 95 % интервалом Уилсона. Набор нельзя принимать только по валидным мешам, не сообщая долю отброшенных.",
        card("Валидность наборов", '<div id="table-f" style="overflow-x:auto"></div>'), anchor="sec-f"))

    body.append(section("Сравнение с генерацией без условия", "Набор без условия должен быть похож на смесь реальных шипиков и отличаться от реальных тормозных; доля тормозных в смеси определяется данными обучения.",
        card("Расстояние набора без условия до реальных групп", '<div id="table-g" style="overflow-x:auto"></div>') + '<p class="small muted" id="note-g"></p>', anchor="sec-g"))

    body.append(section("Методы", "Формулы, нулевые гипотезы и единицы всех проверок.", note(METHODS, title="Методы")))
    body.append(section("Ограничения", "Что эти проверки не гарантируют.", note(LIMITS, title="Ограничения", tone="pink")))
    body.append(f'<footer class="page">Реальные данные: таблица морфометрик этапа 8 ({esc(info.get("morphometrics_table", "—"))}); типы клеток — cell_types_with_nucleus.csv. Расчёт: scripts/neuron_model/conditional_generation_report.py, '
                'статистика: src/neuron_model/spine_generation/evaluation/conditional_tests.py, страница: src/neuron_model/reports/conditional_report.py.</footer>')

    js = (Path(__file__).parent / "assets" / "conditional_report.js").read_text(encoding="utf-8")
    date = str(info.get("created") or "")[:10]
    out = Path(out) if out else folder / f"{date}_conditional-generation-report.html"
    out.write_text(page("Условная генерация: проверка", "".join(body), payload, js), encoding="utf-8")
    return out
